const d = $input.first().json;
if (d.id !== '24cf80b3-5f47-4da6-a6a5-0540b3688343' || d.status !== 'active' || d.pricing_type !== 'free') {
  throw new Error('The selected listing is unavailable or no longer free. Inspect it before continuing.');
}
const count = d.schema?.row_count;
if (!Number.isInteger(count) || count < 1 || count > 1000) {
  throw new Error('The declared row count is outside this bounded export. Inspect the listing.');
}
return [{ json: { declared_rows: count, dataset_id: d.id } }];

const text = $input.first().json.data;
if (typeof text !== 'string' || text.length > 2000000) throw new Error('Expected a bounded NDJSON response.');
const lines = text.trim().split(/\r?\n/).filter(Boolean);
const expected = $('Check free listing').first().json.declared_rows;
if (lines.length !== expected) throw new Error(`Received ${lines.length} rows; listing declares ${expected}. Inspect for truncation or source changes.`);
const fields = ['problem', 'problem_category', 'answer', 'answer_type'];
return lines.map((line, i) => {
  const row = JSON.parse(line);
  if (!row || fields.some(f => typeof row[f] !== 'string')) throw new Error(`Unexpected schema at row ${i + 1}.`);
  return { json: Object.fromEntries(fields.map(f => [f, row[f]])) };
});
